-- PKG_DMF0043 — 클라우드 현재 상태 점검 (SCM_MGR · 조회 전용 · 변경 없음)
-- VERDICT: PRE=사내 적용 전과 동일 → 해당 파일 적용 / POST=이미 적용 → SKIP / ABSENT=없음 / DIFF=클라우드 본문이 다름 → 전체교체 금지·결과 공유
SET PAGESIZE 200 LINESIZE 300
COLUMN OBJ FORMAT A48
COLUMN VERDICT FORMAT A60

-- [A] 교체 대상 객체
SELECT 'PKG_DMF0043' OBJ, 'PACKAGE' TYP, '10_SPEC.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0043' AND OBJECT_TYPE = 'PACKAGE') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0043' AND OBJECT_TYPE = 'PACKAGE') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 277371583227 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 198280763828 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0043' AND TYPE = 'PACKAGE' AND LINE > 1) H;
SELECT 'PKG_DMF0043' OBJ, 'PACKAGE BODY' TYP, '11_BODY.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0043' AND OBJECT_TYPE = 'PACKAGE BODY') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0043' AND OBJECT_TYPE = 'PACKAGE BODY') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 6675452987132 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 3468398654238 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0043' AND TYPE = 'PACKAGE BODY' AND LINE > 1) H;
SELECT 'DMF0043_GET_MAIN_SPREAD_TITLE' OBJ, 'PROCEDURE' TYP, '12_CALLER_DMF0043_GET_MAIN_SPREAD_TITLE.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0043_GET_MAIN_SPREAD_TITLE' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0043_GET_MAIN_SPREAD_TITLE' AND OBJECT_TYPE = 'PROCEDURE') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 411502891212 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 414228002022 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0043_GET_MAIN_SPREAD_TITLE' AND TYPE = 'PROCEDURE' AND LINE > 1) H;

-- [B] DROP 대상 standalone — 멤버 본문 원천. DIFF 면 클라우드에만 있는 수정 → 멤버에 반영 필요(결과 공유)
