SELECT API_ID, API_URL FROM SCM_ADM_API_M WHERE API_ID IN ('DMF0043_GET_CONT_VIEW_VERSIONPOPUP', 'P_DMF0043_MAIN_GET', 'P_DMF0043_MAIN_SAVE', 'P_DMF0043_MAIN_TITLE', 'P_DMF0043_RATE_POPUP', 'P_DMF0043_SALES_LIST_GET', 'P_DMF0043_SALES_LIST_TITLE', 'P_DMF0043_VERSION_GET', 'P_DMF0043_VERSION_POPUP', 'P_DMF0043_VERSION_SAVE', 'P_DMF0043_YEAR_POPUP') ORDER BY API_ID;
SELECT UPPER(PROC_NM) PROC_NM, COUNT(*) CNT FROM SCM_ADM_PROC_M WHERE UPPER(PROC_NM) IN ('DMF0043_GET_CONTRIBUTE_MAIN_DATA', 'DMF0043_GET_CONTRIBUTE_RATE_POPUP', 'DMF0043_GET_CONTRIBUTE_YEAR_POPUP', 'DMF0043_GET_CONTRIBUTION_SALES_LIST', 'DMF0043_GET_CONT_VIEW_VERSIONPOPUP', 'DMF0043_GET_MAIN_SPREAD_TITLE', 'DMF0043_GET_MAIN_VARSION_DATA', 'DMF0043_GET_SALES_LIST_SPREAD_TITLE', 'DMF0043_SAVE_DM_MST_CONTRIBUTE_RATIO', 'DMF0043_SAVE_DM_MST_CONTRIBUTE_VER') OR PROC_NM IN ('PKG_DMF0043.P_DMF0043_GET_CONTRIBUTE_MAIN_DATA', 'PKG_DMF0043.P_DMF0043_GET_CONTRIBUTE_RATE_POPUP', 'PKG_DMF0043.P_DMF0043_GET_CONTRIBUTE_YEAR_POPUP', 'PKG_DMF0043.P_DMF0043_GET_CONTRIBUTION_SALES_LIST', 'PKG_DMF0043.P_DMF0043_GET_CONT_VIEW_VERSIONPOPUP', 'PKG_DMF0043.P_DMF0043_GET_MAIN_SPREAD_TITLE', 'PKG_DMF0043.P_DMF0043_GET_MAIN_VARSION_DATA', 'PKG_DMF0043.P_DMF0043_GET_SALES_LIST_SPREAD_TITLE', 'PKG_DMF0043.P_DMF0043_SAVE_DM_MST_CONTRIBUTE_RATIO', 'PKG_DMF0043.P_DMF0043_SAVE_DM_MST_CONTRIBUTE_VER') GROUP BY UPPER(PROC_NM) ORDER BY 1;

